-- Splynn Dimensional Market: the Power Bow, the winged arrows and the 11 Power Arrow tattoos of printed 104-106.
-- 13 spells rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~357-splynn-tattoos-b.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Tattoo: Bow or Crossbow in Flames (Power Bow)', 0, 0, 'No P.P.E. cost is printed for this tattoo (printed 104-105, 109); 0 is a placeholder, not a free activation.', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.105', 'rifts', 'The bow''s normal reach, usually 600 to 700 feet (183 to 213 m)', NULL, NULL, NULL, NULL, 'One melee action', 'Image: a bow, or a crossbow, wreathed in fire. The magic tattoo weapon that every Power Arrow needs: the arrows can be loosed only from this conjured bow, never from a bow someone built, however enchanted. Part of the Power Arrow magic of the Tattooed Archer (T-Archer), who starts with it. Any other Tattooed Man pays double for his Power Arrows, with half their duration, power and range, until he holds this bow and at least six Power Arrow tattoos. The book prints no cost, duration or damage of its own for the bow; the class page (printed 109) calls it the Bow as a Power Weapon.', NULL, 'tattoo', NULL),
  ('Tattoo: Four Arrows with Wings (winged power arrows)', 0, 20, 'An ADDITIONAL 20 on top of the Power Arrow it is combined with (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.104', 'rifts', 'Three times the bow''s normal range, roughly 2000 feet (610 m)', 'As the Power Arrow it is combined with: 15 minutes per level of experience', NULL, NULL, NULL, 'One melee action', 'Image: four arrows bearing wings. The Power Arrow form of the wing feature, and a separate tattoo from the general Weapon with Wings. Added to most (not all) Power Arrows, it triples how far they fly and brings each arrow straight back to the archer after it strikes, so he has an endless supply for as long as the magic lasts. The Alarm Arrow cannot take it, and Energy Disruption, Lightning and Water Bomb arrows that spend their magic still do not come back.', NULL, 'tattoo', NULL),
  ('Tattoo: Alarm Arrow (power arrow)', 0, 15, 'Cannot take the winged arrows tattoo (printed 105). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.105', 'rifts', 'Heard up to 1 mile (1.6 km) away, or 3 miles (4.8 km) in quiet wilderness or at sea', 'The shriek lasts five minutes', NULL, 'Horror Factor 13; on a failure the listener loses initiative and one attack in the opening round', NULL, 'One melee action', 'Image: one arrow whose head is a screaming mouth. A Power Arrow, fired from the flaming-bow tattoo. Unlike the others it makes only one arrow. Shot skyward, it lets loose a siren wail that hangs in the air for five minutes, meant as a warning or a signal to friends. Anyone hearing it as it starts must save against the Horror Factor or lose an attack and initiative that round. It vanishes into the sky and never comes back.', NULL, 'tattoo', NULL),
  ('Tattoo: Death Arrows (power arrow)', 0, 30, 'Plus 20 with the winged arrows tattoo (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.105', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience', '1D6 direct to Hit Points against mortals, bypassing S.D.C. and body armor; 3D6 M.D. against Mega-Damage creatures', 'Standard save vs magic; a successful save means no damage', NULL, 'One melee action', 'Image: a skull wound about with thorns, beside a broken arrow. A Power Arrow: four arrows, fired from the flaming-bow tattoo, that carry the Death Touch. Against mortals the damage skips S.D.C. and goes to Hit Points, passing through body armor, though power armor, robots and vehicles stop it.', NULL, 'tattoo', NULL),
  ('Tattoo: Energy Disruption Arrow (power arrow)', 0, 30, 'Plus 20 with the winged arrows tattoo, which triples the range but never brings this arrow back (printed 104, 106). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.105-106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', 'The disruption lasts three minutes per level of experience, or until the arrow is pulled out', '1 point on impact; 1D6 M.D. per level of experience if the arrow is pulled out early', NULL, NULL, 'One melee action', 'Image: four arrows crackling with energy. A Power Arrow fired from the flaming-bow tattoo. It barely scratches the target but lodges there and scrambles its energy, as the Energy Disruption spell does (Rifts RPG, p.174). Pulling it out before the magic runs out sets off an explosion, wanted or not. Spent or exploded, it is gone.', NULL, 'tattoo', NULL),
  ('Tattoo: Fire Arrows (power arrow)', 0, 20, 'Plus 20 with the winged arrows tattoo (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience', '2D6 M.D. plus 1 M.D. per level of experience', NULL, NULL, 'One melee action', 'Image: a burning skull or a flaming eye. A Power Arrow: four arrows, loosed from the flaming-bow tattoo, that become bolts of fire in flight. A 3rd level archer''s arrow does 2D6+3 M.D.', NULL, 'tattoo', NULL),
  ('Tattoo: Force Arrows (power arrow)', 0, 15, 'Plus 20 with the winged arrows tattoo (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience', 'The archer''s punch damage for his P.S. as if it were supernatural (usually 3D6 to 5D6 M.D.)', NULL, NULL, 'One melee action', 'Image: a bleeding heart pierced by an arrow. A Power Arrow: four arrows, fired from the flaming-bow tattoo, that land like a blow from someone with supernatural strength.', NULL, 'tattoo', NULL),
  ('Tattoo: Lightning Arrows (power arrow)', 0, 30, 'Plus 20 with the winged arrows tattoo, though these arrows still do not return (printed 104, 106). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience', '1D6 M.D. per level of experience', NULL, NULL, 'One melee action', 'Image: an arrow with lightning bolts streaming from it, or one tipped with a bolt of lightning. A Power Arrow: four arrows, loosed from the flaming-bow tattoo, that turn into small lightning bolts in flight. Each is spent when it hits.', NULL, 'tattoo', NULL),
  ('Tattoo: Psi-Arrows (power arrow)', 0, 30, 'Plus 20 with the winged arrows tattoo (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience', NULL, '14 or higher vs magic; a successful save means no effect', NULL, 'One melee action', 'Image: a cracked or shattered skull. A Power Arrow: four arrows, fired from the flaming-bow tattoo, that fill the target''s head with crippling pain. The effect is the Cracked or Broken Skull power tattoo''s: half the victim''s attacks and speed, -2 on combat bonuses and -25% on most skills.', NULL, 'tattoo', NULL),
  ('Tattoo: Shadow Arrows (power arrow)', 0, 35, 'Plus 20 with the winged arrows tattoo (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience', '2D6 M.D.; double against beings of shadow and night', NULL, NULL, 'One melee action', 'Image: a black sun run through by an arrow. A Power Arrow: four arrows, loosed from the flaming-bow tattoo. Shadow Beasts, Silhouettes, Nightlords, Night Princes, the Nightbane, many Russian demons and other creatures tied to darkness take double damage, as does a mortal mage hidden by Shadow Meld or Cloak of Darkness. The archer''s penalty to strike such beings while they hide in shadow is halved, even when he cannot see them.', NULL, 'tattoo', NULL),
  ('Tattoo: Sight-Stealers (power arrow)', 0, 25, 'Plus 20 with the winged arrows tattoo (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', 'The arrows last 15 minutes per level of experience; the blindness lasts one melee round per level', NULL, 'Standard save vs magic; a successful save means no effect', NULL, 'One melee action', 'Image: an eye with a dagger or an arrow stuck in it. A Power Arrow: four arrows, fired from the flaming-bow tattoo, that blind whoever they strike as the Blind spell does, but only for a melee round per level of the archer.', NULL, 'tattoo', NULL),
  ('Tattoo: Vampire Arrows (power arrow)', 0, 15, 'Plus 20 with the winged arrows tattoo (printed 104). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience', '2D6 S.D.C.; 4D6 direct to Hit Points against vampires', NULL, NULL, 'One melee action', 'Image: a heart with a wooden stake driven through it. A Power Arrow: four arrows, loosed from the flaming-bow tattoo. A shot through a vampire''s heart pins it helpless, exactly as a real wooden shaft would.', NULL, 'tattoo', NULL),
  ('Tattoo: Water Bomb Arrow (power arrow)', 0, 20, 'Plus 20 with the winged arrows tattoo, though arrows spent on a fire or on rain do not return (printed 104, 106). Exclusive to the Tattooed Archer; any other Tattooed Man pays double, with half the duration, power and range, until he holds the Power Bow and six Power Arrow tattoos (printed 105).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.106', 'rifts', 'The bow''s range, usually 600 to 700 feet (183 to 213 m)', '15 minutes per level of experience; a rain burst lasts two minutes per level', '3D4x10 to vampires; 3D6 M.D. to fire-made Elementals, supernatural beings and creatures of magic; none to most others', NULL, NULL, 'One melee action', 'Image: an arrow with rain falling from it. A Power Arrow: four arrows, fired from the flaming-bow tattoo, each landing as a gallon (3.8 liters) of water. Most targets just get soaked. Shot into an ordinary blaze, each arrow puts out a 10 foot (3 m) radius at once. All four loosed straight up within one melee round have a 30% chance, +3% per level, of bringing a light, steady rain, even in a drought: too little for a raging fire, enough for some relief. Also good for pranks on rivals.', NULL, 'tattoo', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 13 spells rows are in' AS assertion, count(*) AS got, 13 AS want
  FROM spells WHERE name IN ('Tattoo: Bow or Crossbow in Flames (Power Bow)', 'Tattoo: Four Arrows with Wings (winged power arrows)', 'Tattoo: Alarm Arrow (power arrow)', 'Tattoo: Death Arrows (power arrow)', 'Tattoo: Energy Disruption Arrow (power arrow)', 'Tattoo: Fire Arrows (power arrow)', 'Tattoo: Force Arrows (power arrow)', 'Tattoo: Lightning Arrows (power arrow)', 'Tattoo: Psi-Arrows (power arrow)', 'Tattoo: Shadow Arrows (power arrow)', 'Tattoo: Sight-Stealers (power arrow)', 'Tattoo: Vampire Arrows (power arrow)', 'Tattoo: Water Bomb Arrow (power arrow)') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~357-splynn-tattoos-b.sql');
